@startuml

class Bookmaker {
  + ManageBettors()
  + AcceptBet(bet: Bet)
  + DetermineTotalWinningsAndLosses()
}

class Bettor {
  + Name : string
}

class Race {
  + NumberOfRunners : int
  + Winner : Runner
}

class Runner {
  + Name : string
}

class Jockey {
  + Name : string
}

class Bet {
  + Amount : double
  + Odds : double
}

Bettor "1" -- "*" Bet : places
Bet "1" -- "1" Race : refers to
Bet "1" -- "1" Runner : refers to
Race "1" -- "1..*" Runner : has
Runner "1" -- "1" Jockey : is ridden by

@enduml

